const WMO = {
  0: ['☀️', 'Ясно'], 1: ['🌤', 'Преимущественно ясно'], 2: ['⛅', 'Переменная облачность'], 3: ['☁️', 'Пасмурно'],
  45: ['🌫', 'Туман'], 48: ['🌫', 'Изморозевый туман'],
  51: ['🌦', 'Лёгкая морось'], 53: ['🌦', 'Морось'], 55: ['🌧', 'Сильная морось'],
  56: ['🌧', 'Ледяная морось'], 57: ['🌧', 'Сильная ледяная морось'],
  61: ['🌦', 'Небольшой дождь'], 63: ['🌧', 'Дождь'], 65: ['🌧', 'Сильный дождь'],
  66: ['🌧', 'Ледяной дождь'], 67: ['🌧', 'Сильный ледяной дождь'],
  71: ['🌨', 'Небольшой снег'], 73: ['🌨', 'Снег'], 75: ['❄️', 'Сильный снег'], 77: ['🌨', 'Снежные зёрна'],
  80: ['🌦', 'Небольшой ливень'], 81: ['🌧', 'Ливень'], 82: ['⛈', 'Сильный ливень'],
  85: ['🌨', 'Небольшой снегопад'], 86: ['❄️', 'Сильный снегопад'],
  95: ['⛈', 'Гроза'], 96: ['⛈', 'Гроза с градом'], 99: ['⛈', 'Сильная гроза с градом']
};
const norm = s => String(s || '').toLowerCase().replace(/ё/g, 'е').trim();
const stem = s => norm(s).slice(0, 5).trim();
const clean = s => String(s == null ? '' : s).replace(/[_*`\[\]]/g, ' ').trim();
const sleep = ms => new Promise(r => setTimeout(r, ms));
let lastNominatim = 0;

const regionFull = (name, type) => {
  const t = norm(type);
  if (!name) return '';
  if (t.startsWith('аобл')) return `${name} автономная область`;
  if (t.startsWith('обл')) return `${name} область`;
  if (t.startsWith('край')) return `${name} край`;
  if (t.startsWith('респ')) return `Республика ${name}`;
  if (t === 'ао') return `${name} автономный округ`;
  return name;
};

async function geocode(loc) {
  const parts = [loc.name];
  if (loc.parent_name && !loc.parent_is_region) parts.push(norm(loc.parent_type).startsWith('р-н') ? `${loc.parent_name} район` : loc.parent_name);
  const region = regionFull(loc.region_name, loc.region_type);
  if (region) parts.push(region);
  const seen = new Set();
  const q = parts.filter(p => { const k = norm(p); if (!k || seen.has(k)) return false; seen.add(k); return true; }).join(', ');

  // 1) Nominatim (не чаще 1 запроса в секунду)
  try {
    const wait = 1100 - (Date.now() - lastNominatim);
    if (wait > 0) await sleep(wait);
    lastNominatim = Date.now();
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://nominatim.openstreetmap.org/search',
      qs: { q, format: 'json', limit: 1, countrycodes: 'ru', 'accept-language': 'ru' },
      headers: { 'User-Agent': 'WeatherBot/1.0' }, json: true, timeout: 10000 });
    const f = Array.isArray(r) ? r[0] : null;
    if (f && Number.isFinite(parseFloat(f.lat)) && Number.isFinite(parseFloat(f.lon)))
      return { lat: parseFloat(f.lat), lon: parseFloat(f.lon), source: 'nominatim' };
  } catch (e) {}

  // 2) Open-Meteo Geocoding: то же имя и тот же регион
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://geocoding-api.open-meteo.com/v1/search',
      qs: { name: loc.name, count: 20, language: 'ru', format: 'json', countryCode: 'RU' }, json: true, timeout: 10000 });
    let c = (Array.isArray(r.results) ? r.results : []).filter(x => norm(x.name) === norm(loc.name));
    if (loc.region_name) c = c.filter(x => norm(x.admin1).includes(stem(loc.region_name)));
    const pn = (!loc.parent_is_region && norm(loc.parent_type).startsWith('р-н')) ? loc.parent_name : '';
    if (pn) { const bp = c.filter(x => norm(x.admin2).includes(stem(pn))); if (bp.length) c = bp; }
    if (c.length && Number.isFinite(c[0].latitude) && Number.isFinite(c[0].longitude))
      return { lat: c[0].latitude, lon: c[0].longitude, source: 'open-meteo' };
  } catch (e) {}
  return null;
}

const out = [];
for (const it of $input.all()) {
  const loc = it.json;
  let lat = loc.lat, lon = loc.lon, source = '', save = false, usedParent = false;

  if (lat === null || lat === undefined) {
    const g = await geocode.call(this, loc);
    if (g) { lat = g.lat; lon = g.lon; source = g.source; save = true; }
    else if (loc.parent_lat !== null && loc.parent_lat !== undefined) { lat = loc.parent_lat; lon = loc.parent_lon; usedParent = true; }
    else continue;
  }

  let cw = null;
  for (let attempt = 0; attempt < 2 && !cw; attempt++) {
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.open-meteo.com/v1/forecast',
        qs: { latitude: lat, longitude: lon, current_weather: true }, json: true, timeout: 10000 });
      if (r && r.current_weather && r.current_weather.temperature !== undefined) cw = r.current_weather;
    } catch (e) { await sleep(1500); }
  }
  if (!cw) continue;

  const temp = Math.round(cw.temperature), wind = Math.round(cw.windspeed);
  const [emoji, desc] = WMO[cw.weathercode] || ['🌡', `Код погоды ${cw.weathercode}`];
  const title = loc.name_prep ? `Погода ${clean(loc.name_prep)}` : `Погода: ${clean(loc.name)}`;
  let suffix = '';
  if (loc.parent_name && !loc.parent_is_region && ['city_district', 'locality', 'settlement', 'district'].includes(loc.kind)) {
    suffix = ` (${clean(loc.parent_name)}${norm(loc.parent_type).startsWith('р-н') ? ' район' : ''})`;
  }
  let text = `🔔 *${title}${suffix}*\n\n${emoji} ${desc}, ${temp > 0 ? '+' : ''}${temp}°C\n💨 Ветер: ${wind} км/ч`;
  if (usedParent) text += `\n\n_ℹ️ Координаты района не найдены, показана погода по городу._`;

  out.push({ json: { chat_id: loc.telegram_id, text, id: loc.id, lat, lon, source, save_coords: save } });
}
return out;
